def is_3colorable_check(edges, n):
    # Try 3-coloring via backtracking
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    color=[-1]*n
    order = sorted(range(n), key=lambda x:-len(adj[x]))
    def bt(i):
        if i==n: return True
        v=order[i]
        used=set(color[u] for u in adj[v] if color[u]!=-1)
        for c in range(3):
            if c not in used:
                color[v]=c
                if bt(i+1): return True
                color[v]=-1
        return False
    return bt(0)

